// Auth, parse payload, and forward to Arduino (paste exactly)
const EXPECTED = (typeof env !== 'undefined' && env.get('RELAY_API_KEY')) || 'a517604f0c112f1082111d058ed249ac';

try { node.warn("Headers: " + JSON.stringify(msg.req && msg.req.headers || {})); } catch (e) { }
try { node.warn("Raw payload: " + JSON.stringify(msg.payload)); } catch (e) { }

// Parse payload if it's a string
if (typeof msg.payload === 'string') {
  try { msg.payload = JSON.parse(msg.payload); }
  catch (e) {
    msg.statusCode = 400; msg.payload = { ok: false, error: 'Invalid JSON' }; return [null, msg];
  }
}

// Show parsed payload for debugging
try { node.warn("Parsed payload: " + JSON.stringify(msg.payload)); } catch (e) { }

const body = msg.payload || {};
if (!body.room || !body.action) {
  msg.statusCode = 400; msg.payload = { ok: false, error: 'Missing room or action' }; return [null, msg];
}

// Auth check
const auth = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
if (!auth || !auth.startsWith('Bearer ')) {
  msg.statusCode = 401; msg.payload = { ok: false, error: 'Missing Authorization' }; return [null, msg];
}
const key = auth.slice(7).trim();
if (key !== EXPECTED) {
  msg.statusCode = 401; msg.payload = { ok: false, error: 'Unauthorized', gotKey: key }; return [null, msg];
}

// Build forward request
msg.method = 'POST';
msg.url = 'http://192.168.0.196:8080/command'; // <- ensure this matches the IP printed by the Arduino Serial Monitor
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { room: body.room, action: body.action, timer: Number(body.timer) || 0 };

// Final debug
try { node.warn("Forwarding to: " + msg.url + " payload: " + JSON.stringify(msg.payload)); } catch (e) { }

return [msg, null];

// msg.payload contains device response (text). Try parse JSON
let deviceResp = null;
try { deviceResp = JSON.parse(msg.payload); } catch(e) { deviceResp = msg.payload; }
msg.res = msg.res || {};
msg.statusCode = 200;
msg.payload = { ok: true, device: deviceResp };
return msg;

